const now = new Date();
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0));
const ymd = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    start_date: ymd(start),
    end_date: ymd(end),
  },
}];

function collect(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  if (items.length === 1 && Array.isArray(items[0])) return items[0];
  return items.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
}

const period = $('Prepare Last Month').first().json;
const groups = collect('Get Connector Groups');
const connectors = collect('Get Connectors');

const groupsById = Object.fromEntries(
  groups.map((g) => [String(g.id), g]),
);

const catalog = connectors.map((c) => {
  const group = groupsById[String(c.company_id)] || {};
  return {
    connector_id: c.id,
    username: c.username,
    carrier: c.carrier,
    carrier_display_name: c.carrier_display_name || c.carrier,
    enabled: c.enabled,
    status: c.status,
    connector_group_id: c.company_id,
    connector_group_name: group.display_name || group.name || c.company_name || '',
  };
});

return [{
  json: {
    start_date: period.start_date,
    end_date: period.end_date,
    connector_group_count: groups.length,
    connector_count: connectors.length,
    groups: groups.map((g) => ({
      connector_group_id: g.id,
      connector_group_name: g.display_name || g.name || '',
    })),
    catalog,
  },
}];

const catalog = $('Build Catalog').first().json;
const response = $input.first().json;
let invoices = Array.isArray(response.invoices)
  ? response.invoices
  : Array.isArray(response)
    ? response
    : [];

const seen = new Set();
invoices = invoices.filter((inv) => {
  const key = [inv.credential_id, inv.invoice_number, inv.invoice_date].join('|');
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const byConnector = new Map();
for (const c of catalog.catalog || []) {
  byConnector.set(String(c.connector_id), {
    ...c,
    invoice_count: 0,
  });
}

const byGroup = new Map();
for (const g of catalog.groups || []) {
  byGroup.set(String(g.connector_group_id), {
    ...g,
    invoice_count: 0,
    connector_count: 0,
  });
}
for (const c of catalog.catalog || []) {
  const key = String(c.connector_group_id);
  if (!byGroup.has(key)) {
    byGroup.set(key, {
      connector_group_id: c.connector_group_id,
      connector_group_name: c.connector_group_name || '',
      invoice_count: 0,
      connector_count: 0,
    });
  }
  byGroup.get(key).connector_count += 1;
}

for (const inv of invoices) {
  const connectorKey = String(inv.credential_id);
  if (!byConnector.has(connectorKey)) {
    byConnector.set(connectorKey, {
      connector_id: inv.credential_id,
      username: '',
      carrier: inv.carrier || '',
      connector_group_id: inv.company_id,
      connector_group_name: '',
      invoice_count: 0,
    });
  }
  byConnector.get(connectorKey).invoice_count += 1;

  const groupKey = String(
    byConnector.get(connectorKey).connector_group_id ?? inv.company_id,
  );
  if (!byGroup.has(groupKey)) {
    byGroup.set(groupKey, {
      connector_group_id: Number(groupKey) || groupKey,
      connector_group_name: byConnector.get(connectorKey).connector_group_name || '',
      invoice_count: 0,
      connector_count: 0,
    });
  }
  byGroup.get(groupKey).invoice_count += 1;
}

const connectors = [...byConnector.values()].sort(
  (a, b) => b.invoice_count - a.invoice_count,
);
const groups = [...byGroup.values()].sort(
  (a, b) => b.invoice_count - a.invoice_count,
);

return [{
  json: {
    period: {
      start_date: catalog.start_date,
      end_date: catalog.end_date,
    },
    connector_group_count: catalog.connector_group_count,
    connector_count: catalog.connector_count,
    invoice_count: invoices.length,
    groups,
    connectors,
  },
}];
